INSERT IGNORE INTO spawn2_before_era SELECT * FROM spawn2 WHERE zone = 'sirens' AND id < 1000000;
INSERT IGNORE INTO grid_before_era SELECT * FROM grid WHERE zoneid = 125 AND EXISTS (SELECT 1 FROM spawn2 WHERE zone = 'sirens' AND id < 1000000);
INSERT IGNORE INTO grid_entries_before_era SELECT * FROM grid_entries WHERE zoneid = 125 AND EXISTS (SELECT 1 FROM spawn2 WHERE zone = 'sirens' AND id < 1000000);
INSERT IGNORE INTO spawngroup_before_era SELECT * FROM spawngroup WHERE id IN (SELECT id FROM era_groups);
INSERT IGNORE INTO spawnentry_before_era SELECT * FROM spawnentry WHERE spawngroupID IN (SELECT id FROM era_groups);
