-- 020: sirens as it was from Classic to Velious (spawn points, groups and path grids from Quarm).
--
-- The dump has this zone in a later, revamped state. Generated by tools/npc_stats/gen_zone_from_quarm.py
-- (regenerate rather than edit): 159 spawn points, 58 spawn groups, 137 entries from the Quarm database,
-- ids + 1000000. NPCs are ours, matched by name; headings are Quarm's / 1.0198.
-- Level, HP, damage and AC taken from Quarm: a_neriad_mistress: ours 125033 was level 55, Quarm has 49
-- Level, HP, damage and AC taken from Quarm: an_enthralled_bulthar: ours 125024 was level 51, Quarm has 47
-- Level, HP, damage and AC taken from Quarm: a_siren_seductress: ours 125038 was level 55, Quarm has 50
-- Level, HP, damage and AC taken from Quarm: an_enthralled_ulthork: ours 125035 was level 55, Quarm has 47
-- Level, HP, damage and AC taken from Quarm: an_enthralled_molkor: ours 125012 was level 51, Quarm has 47
-- Level, HP, damage and AC taken from Quarm: a_servant_manatee: ours 125044 was level 51, Quarm has 47
-- Level, HP, damage and AC taken from Quarm: #Mistress_Latazura: ours 125047 was level 61, Quarm has 66
-- Imported from Quarm (basic stats, loot table, faction list when we have none for the name): agent_of_druzzil as npc_types 1200021
--
-- Our rows are kept in spawn2_before_era, spawngroup_before_era, spawnentry_before_era, grid_before_era and
-- grid_entries_before_era. To restore: delete the zone's rows with id >= 1000000 (spawn2, and spawngroup /
-- spawnentry by spawngroupID), delete its grid / grid_entries rows, and insert the *_before_era rows back.
-- Idempotent.

CREATE TABLE IF NOT EXISTS spawn2_before_era LIKE spawn2;
CREATE TABLE IF NOT EXISTS spawngroup_before_era LIKE spawngroup;
CREATE TABLE IF NOT EXISTS spawnentry_before_era LIKE spawnentry;
CREATE TABLE IF NOT EXISTS grid_before_era LIKE grid;
CREATE TABLE IF NOT EXISTS grid_entries_before_era LIKE grid_entries;
CREATE TEMPORARY TABLE era_groups AS SELECT DISTINCT spawngroupID AS id FROM spawn2 WHERE zone = 'sirens' AND id < 1000000
  AND spawngroupID NOT IN (SELECT spawngroupID FROM spawn2 WHERE zone <> 'sirens');
DELETE FROM spawnentry WHERE spawngroupID IN (SELECT id FROM era_groups);
DELETE FROM spawngroup WHERE id IN (SELECT id FROM era_groups);
DELETE FROM spawn2 WHERE zone = 'sirens' AND id < 1000000;
DROP TEMPORARY TABLE era_groups;
DELETE FROM grid_entries WHERE zoneid = 125;
DELETE FROM grid WHERE zoneid = 125;



CREATE TABLE IF NOT EXISTS npc_types_before_era LIKE npc_types;
UPDATE npc_types SET level = 47, hp = 9944, mindmg = 38, maxdmg = 131, AC = 177 WHERE id = 125012;
